import React, { createContext, useContext, useEffect, useMemo, useRef, useState } from "react";
import axios from "axios";
import { API_BASE_URL } from "../config";

const HematrikDataContext = createContext(null);

export function HematrikDataProvider({ children, pollMs = 3000 }) {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const mountedRef = useRef(true);

  const loadData = async () => {
    try {
      setError(null);
      const res = await axios.get(`${API_BASE_URL}/data`);
      if (!mountedRef.current) return;
      setData(Array.isArray(res.data) ? res.data : []);
    } catch (err) {
      if (!mountedRef.current) return;
      setError(err);
    } finally {
      if (!mountedRef.current) return;
      setLoading(false);
    }
  };

  useEffect(() => {
    mountedRef.current = true;
    loadData();

    const interval = setInterval(loadData, pollMs);
    return () => {
      mountedRef.current = false;
      clearInterval(interval);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pollMs]);

  const latest = data.length > 0 ? data[0] : null;

  const value = useMemo(
    () => ({
      data,
      latest,
      loading,
      error,
      reload: loadData
    }),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [data, latest, loading, error]
  );

  return <HematrikDataContext.Provider value={value}>{children}</HematrikDataContext.Provider>;
}

export function useHematrikData() {
  const ctx = useContext(HematrikDataContext);
  if (!ctx) {
    throw new Error("useHematrikData must be used within HematrikDataProvider");
  }
  return ctx;
}
